-- Create metrics table
CREATE TABLE metrics (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT UNIQUE,
  description TEXT,
  type TEXT, -- e.g., 'Time', 'Ratio', 'Count', etc.
  metadata JSONB, -- stores associations to views, goals, sources, etc.
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Optional: Index for faster metadata queries
CREATE INDEX metrics_metadata_gin ON metrics USING GIN (metadata);

